const requestBody = $('Email draft request').first().json.body || {};
const inboundText = String(requestBody.body_text || requestBody.bodyText || '').toLowerCase();
const subjectText = String(requestBody.subject || '').toLowerCase();
const fullText = `${subjectText}\n${inboundText}`;

function extractModelText(value) {
  if (typeof value === 'string') return value;

  if (Array.isArray(value)) {
    for (const item of value) {
      const extracted = extractModelText(item);
      if (extracted) return extracted;
    }
    return '';
  }

  if (!value || typeof value !== 'object') return '';

  if (typeof value.text === 'string') return value.text;
  if (typeof value.output_text === 'string') return value.output_text;
  if (typeof value.content === 'string') return value.content;

  if (Array.isArray(value.content)) {
    return extractModelText(value.content);
  }

  if (Array.isArray(value.output)) {
    return extractModelText(value.output);
  }

  if (value.message) return extractModelText(value.message);
  if (value.response) return extractModelText(value.response);

  return '';
}

const nonActionablePattern = /(newsletter|unsubscribe|no[- ]?reply|noreply|mailer-daemon|delivery status notification|undelivered mail|out of office|fuera de la oficina|resposta autom[aà]tica|respuesta autom[aá]tica)/i;
const actionablePattern = /(\?|\bhorari|\bhorarios|\bhoraire|\bopening hours|\bentrad|\bticket|\bprecio|\bpreu|\bprice|\bdescompte|\bdescuento|\bdiscount|\bgrupo|\bgrup|\bgroup|\baccessibil|\bubicaci|\bdirecci|\bprogramaci|\bcartelera|\bagenda|\bvisita|\bcontact|\bdevoluci|\brefund|\bvoldria|\bqueria|\bquisiera|\bcan you|\bcould you|\bhi ha|\bhay|\bteniu|\bten[eé]is)/i;
const isNonActionable = nonActionablePattern.test(fullText) && !actionablePattern.test(fullText);
const isActionable = actionablePattern.test(fullText) || inboundText.trim().length > 20;

const raw = extractModelText($json) || '';
let parsed;

try {
  parsed = typeof raw === 'string'
    ? JSON.parse(raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim())
    : raw;
} catch (error) {
  parsed = {
    should_reply: true,
    subject: null,
    body_text: String(raw || '').trim() || 'No he podido generar una respuesta fiable. Por favor, revisa este email manualmente.',
    body_html: null,
    topic: 'otro',
    priority: 'normal',
    confidence: 0,
    escalation_reason: 'invalid_model_json'
  };
}

let shouldReply = Boolean(parsed.should_reply || parsed.shouldReply);
if (isActionable && !isNonActionable) shouldReply = true;
if (isNonActionable) shouldReply = false;

const topic = parsed.topic || parsed.category || (fullText.match(/horari|horarios/) ? 'horarios' : 'otro');
const fallbackBody = 'Hola, gracias por contactar. Hemos recibido tu consulta y te dejamos este borrador para revisión del equipo de atención. Si necesitas una respuesta más precisa, revisa la información del cliente antes de enviar.';

return [{
  json: {
    should_reply: shouldReply,
    subject: parsed.subject || (requestBody.subject ? `Re: ${requestBody.subject}` : null),
    body_text: parsed.body_text || parsed.bodyText || (shouldReply ? fallbackBody : null),
    body_html: parsed.body_html || parsed.bodyHtml || null,
    topic,
    priority: ['low', 'normal', 'high', 'urgent'].includes(parsed.priority) ? parsed.priority : 'normal',
    confidence: typeof parsed.confidence === 'number' ? parsed.confidence : null,
    escalation_reason: parsed.escalation_reason || parsed.escalationReason || null
  }
}];
